cd /home/runner/fwork/chandler; git fetch origin '+refs/heads/friend/*:refs/remotes/origin/friend/*' --quiet; python3 - <<'EOF'
import re,subprocess,glob,os
os.chdir('/home/runner/fwork/main')
mis=[]
for f in sorted(glob.glob('S01/*.md')):
    t=open(f,encoding='utf-8').read()
    for spk,ts,branch,sha in re.findall(r'^\*\*(.+?)\*\* \((\d{4}-[^)]+Z)\)\n\nSource: (friend/\w+) @ ([0-9a-f]{40})',t,re.M):
        body=subprocess.run(['git','-C','/home/runner/fwork/chandler','log','-1','--format=%b',sha],capture_output=True,text=True).stdout
        decl=re.search(r'^Episode: (\S+)',body,re.M)
        dsp=re.search(r'^Speaker: (\w+)',body,re.M)
        want=os.path.basename(f).replace('.md','')
        want=f"S01/{want}"
        if not decl or decl.group(1)!=want: mis.append((f,sha,'episode',decl.group(1) if decl else None))
        if dsp and dsp.group(1)!=spk: mis.append((f,sha,'speaker',dsp.group(1)))
        if branch.rsplit('/',1)[1].lower()!=spk.lower(): mis.append((f,sha,'branch/speaker',branch))
print("misplacements:",len(mis))
for m in mis[:10]: print(m)
EOF
